function totalMs(loginMs, guesses) {
  return loginMs * guesses;
}

function costAfterSteps(baseMs, steps) {
  return baseMs * 2 ** steps;
}

function isFastEnough(loginMs, budgetMs) {
  return loginMs <= budgetMs;
}

function slowdown(oldMs, newMs) {
  return newMs / oldMs;
}

function attackDaysParallel(loginMs, guesses, cores) {
  return (loginMs * guesses) / (cores * 86400000);
}

function stepsToReach(baseMs, targetMs) {
  let steps = 0;
  let ms = baseMs;
  while (ms < targetMs) {
    ms *= 2;
    steps += 1;
  }
  return steps;
}

function bestCost(baseMs, budgetMs) {
  if (baseMs > budgetMs) return -1;
  let steps = 0;
  while (baseMs * 2 ** (steps + 1) <= budgetMs) {
    steps += 1;
  }
  return steps;
}
